 #define GET(field,k) path(key,prefix,i,k);text(key,p.field,sizeof p.field)
 GET(id,sky?"0":"hex");if(!p.id[0])continue;GET(callsign,sky?"1":"flight");while(len(p.callsign)&&p.callsign[len(p.callsign)-1]==' ')p.callsign[len(p.callsign)-1]=0;if(!p.callsign[0])cp(p.callsign,p.id,sizeof p.callsign);GET(registration,"r");GET(type,"t");GET(description,"desc");GET(country,sky?"2":"country");GET(squawk,sky?"14":"squawk");GET(category,sky?"17":"category");
 #undef GET
 path(key,prefix,i,sky?"8":"alt_baro");text(key,alt,sizeof alt);p.ground=eq(alt,sky?"true":"ground");if(hide_ground&&p.ground)continue;p.alt=real_at(prefix,i,sky?"7":"alt_baro",-1);if(!sky&&p.alt>=0)p.alt/=3.28084;p.speed=real_at(prefix,i,sky?"9":"gs",0)/(sky?1:1.943844);p.heading=real_at(prefix,i,sky?"10":"track",-1);p.heading_valid=p.heading>=0;if(!p.heading_valid)p.heading=0;p.vertical=real_at(prefix,i,sky?"11":"baro_rate",0)*(sky?1:0.00508);path(key,prefix,i,"dbFlags");p.military=integer(key,0)&1;p.distance=distance(latitude,longitude,p.lat,p.lon);if(p.distance>range_km)continue;
