__attribute__((visibility("default"))) int gadget_app_entry(int argc,char**argv){gadget_app_lifecycle*life;if(init(argc,argv,&life))return -1;life->shutdown=shutdown;latitude=longitude=0;range_km=25;metric=1;hide_ground=override_location=0;count=trail_count=generation=provider=0;view=busy=0;selected_id[0]=notice[0]=route[0]=route_call[0]=origin[0]=destination[0]=0;char data[1024],s[40];int n=svc->config_read(data,sizeof data);if(n>0&&svc->json_open(data,n)==0){double v;if(text("center_latitude",s,sizeof s)>0&&decimal(s,&v)&&absval(v)<=90){latitude=v;override_location=1;}if(text("center_longitude",s,sizeof s)>0&&decimal(s,&v)&&absval(v)<=180)longitude=v;else override_location=0;if(text("range_km",s,sizeof s)>0&&decimal(s,&v)&&v>=0.1&&v<=20000)range_km=v;if(text("override_location",s,sizeof s)>=0)override_location=eq(s,"true");if(text("metric",s,sizeof s)>=0)metric=eq(s,"true");hide_ground=boolean("hide_ground");svc->json_close();}zero(&airports,sizeof airports);int bytes=svc->cache_read(&airports,sizeof airports);if(bytes!=sizeof airports||!valid_airports())zero(&airports,sizeof airports);reset_area();resolve_location();next_request=svc->monotonic_ms();last_refresh=next_request-15000;root=ui->create(0,GADGET_UI_ROOT,"",0,0);if(!root||ui->reserve(192)<0||!host->timer_create(250,tick,0))return -1;if(settings_entry)settings(0);render();dirty=0;return 0;}
